#!/usr/bin/env node
/**
 * Generate _STATE.md from _state/shared plus each seat's STATE.md.
 * Combined view is generated. Seats write their own file. Do not edit
 * _STATE.md by hand; check-generated fails if it drifts.
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { loadSeatRegister } from '../enforcement/seat-register.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '../..');
const STATE_DIR = join(ROOT, '_state');
const OUT = join(ROOT, '_STATE.md');

function readIfExists(p) {
  if (!existsSync(p)) return null;
  return readFileSync(p, 'utf8').replace(/\r\n/g, '\n').replace(/^\uFEFF/, '');
}

export function renderCombined(root = ROOT) {
  const register = loadSeatRegister();
  const parts = [];
  const stamp = new Date().toISOString();
  parts.push(`# _STATE — living program state (GENERATED, read this FIRST, every session)`);
  parts.push('');
  parts.push(`This file is generated by \`scripts/state/generate-combined.mjs\`. Do not edit it. Each planner seat writes \`_state/<namespace>/STATE.md\`. Shared standing decisions live in \`_state/shared/STANDING_DECISIONS.md\`. Last generated: ${stamp}.`);
  parts.push('');
  parts.push('## Seat index');
  parts.push('');
  for (const seat of register.seats) {
    parts.push(`- **${seat.name}** (\`${seat.branch}\`): \`_state/${seat.namespace}/STATE.md\` worktree \`${seat.worktree}\``);
  }
  parts.push(`- **integration** (not a seat): \`${register.integration.worktree}\` on \`${register.integration.branch}\``);
  parts.push('');

  const standing = readIfExists(join(root, '_state/shared/STANDING_DECISIONS.md'));
  if (standing) {
    parts.push(standing.trim());
    parts.push('');
  }

  for (const seat of register.seats) {
    const body = readIfExists(join(root, '_state', seat.namespace, 'STATE.md'));
    parts.push(`---`);
    parts.push('');
    parts.push(`# Seat: ${seat.name}`);
    parts.push('');
    if (!body) {
      parts.push(`_No state file yet. Seat writes \`_state/${seat.namespace}/STATE.md\`._`);
    } else {
      parts.push(body.trim());
    }
    parts.push('');
  }
  return parts.join('\n').replace(/\n+$/, '') + '\n';
}

function main() {
  mkdirSync(STATE_DIR, { recursive: true });
  const combined = renderCombined();
  writeFileSync(OUT, combined, 'utf8');
  console.log(JSON.stringify({ generated: '_STATE.md', bytes: combined.length, seats: loadSeatRegister().seats.map((s) => s.name) }));
}

const isMain = process.argv[1] && /generate-combined\.mjs$/i.test(process.argv[1].replace(/\\/g, '/'));
if (isMain) main();
